package com.arjunren.loan.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="repayments",indexes=@Index(name="repayments_loan_paid_idx",columnList="loan_id,paid_at")) public class Repayment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="loan_id")private LoanApplication loan;@Column(nullable=false,precision=19,scale=2)private BigDecimal amount;@Column(nullable=false,unique=true,length=50)private String reference;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="recorded_by")private AppUser recordedBy;@Column(name="paid_at",nullable=false,updatable=false)private Instant paidAt=Instant.now();protected Repayment(){}public Repayment(LoanApplication l,BigDecimal a,String r,AppUser u){loan=l;amount=a;reference=r;recordedBy=u;}public Long getId(){return id;}public Long getLoanId(){return loan.getId();}public BigDecimal getAmount(){return amount;}public String getReference(){return reference;}public Instant getPaidAt(){return paidAt;}}

